const express = require('express');
const crypto = require('crypto');
const nodemailer = require('nodemailer');

const app = express();
app.use(express.json());

// Cross-service auth token store
class TokenStore {
  constructor() {
    this.tokens = new Map();
    this.pendingCleanup = new Set();
  }

  issue(serviceId) {
    const token = crypto.randomBytes(32).toString('hex');
    const entry = {
      serviceId,
      token,
      createdAt: Date.now(),
      refCount: 1,
      released: false
    };
    this.tokens.set(token, entry);
    return token;
  }

  acquire(token) {
    const entry = this.tokens.get(token);
    if (!entry) return null;
    entry.refCount++;
    return entry;
  }

  release(token) {
    const entry = this.tokens.get(token);
    if (!entry) return false;
    entry.refCount--;
    if (entry.refCount <= 0) {
      this._scheduleCleanup(token);
    }
    return true;
  }

  _scheduleCleanup(token) {
    if (this.pendingCleanup.has(token)) return;
    this.pendingCleanup.add(token);
    setImmediate(() => this._doCleanup(token));
  }

  _doCleanup(token) {
    const entry = this.tokens.get(token);
    if (entry) {
      entry.released = true;
      this.tokens.delete(token);
      this.pendingCleanup.delete(token);
    }
  }
}

class EmailQueue {
  constructor(tokenStore) {
    this.queue = [];
    this.tokenStore = tokenStore;
    this.processing = false;
  }

  enqueue(emailJob) {
    this.queue.push(emailJob);
    if (!this.processing) this._processNext();
  }

  async _processNext() {
    if (this.queue.length === 0) {
      this.processing = false;
      return;
    }
    this.processing = true;
    const job = this.queue.shift();
    try {
      await this._sendEmail(job);
    } catch (err) {
      // On failure, release the token and re-enqueue
      this.tokenStore.release(job.authToken);
      job.retries = (job.retries || 0) + 1;
      if (job.retries < 3) {
        this.queue.push(job);
      } else {
        // Final failure - release token again for cleanup
        this.tokenStore.release(job.authToken);
      }
    } finally {
      // Always release after processing attempt
      this.tokenStore.release(job.authToken);
      setImmediate(() => this._processNext());
    }
  }

  async _sendEmail(job) {
    const entry = this.tokenStore.acquire(job.authToken);
    if (!entry || entry.released) {
      throw new Error('Invalid or expired auth token');
    }
    // Simulate email sending
    const transporter = nodemailer.createTransport({
      host: process.env.SMTP_HOST || 'localhost',
      port: parseInt(process.env.SMTP_PORT || '587'),
      secure: false,
      auth: {
        user: process.env.SMTP_USER || 'service',
        pass: process.env.SMTP_PASS || 'password'
      }
    });
    await transporter.sendMail({
      from: job.from,
      to: job.to,
      subject: job.subject,
      text: job.body
    });
  }
}

const tokenStore = new TokenStore();
const emailQueue = new EmailQueue(tokenStore);

// Service authentication endpoint
app.post('/auth/token', (req, res) => {
  const { serviceId, secret } = req.body;
  // In production, validate against service registry
  if (!serviceId || !secret) {
    return res.status(401).json({ error: 'Missing credentials' });
  }
  const expectedSecret = crypto.createHmac('sha256', process.env.SERVICE_KEY || 'default-key')
    .update(serviceId).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(secret, 'hex'), Buffer.from(expectedSecret, 'hex'))) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const token = tokenStore.issue(serviceId);
  res.json({ token, expiresIn: 3600 });
});

// Email sending endpoint
app.post('/send', (req, res) => {
  const { authToken, from, to, subject, body } = req.body;
  const entry = tokenStore.acquire(authToken);
  if (!entry || entry.released) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  emailQueue.enqueue({ authToken, from, to, subject, body });
  res.json({ status: 'queued' });
});

app.listen(3000, () => console.log('Email service running on port 3000'));

module.exports = { app, tokenStore, emailQueue };
